/**
 * Decision-fact standards (docs/product/ai-brand-perception/decision-fact-standards.md): 5–10 facts per business type
 * in two buckets, Core and When relevant, versioned and approved by the owner. New types are added here only after
 * review; never generated by a model.
 */
export type Bucket = "core" | "relevant";
export type DecisionFact = {
  id: string;
  bucket: Bucket;
  /** Row name in the report. */
  name: string;
  /** What a complete answer covers (shown under the name, and given to the assessors). */
  lookFor: string;
  /** The customer's question, as put to each AI. */
  question: string;
};
export type Standard = { id: string; version: string; label: string; approved: string; match: RegExp; facts: DecisionFact[] };

